/*
 * pic_scenario.h
 * ─────────────────────────────────────────────────────────────────────────────
 * Compiled-in UI artwork for GEVITON SMART TAG.
 *
 * HOW TO ADD / UPDATE ARTWORK
 * ─────────────────────────────────────────────────────────────────────────────
 *  1. Design the screen in Canva at exactly 400 × 300 px.
 *     Use only pure black (#000000) and pure white (#FFFFFF).
 *     Export as PNG (400×300 px).
 *
 *  2. Convert with https://javl.github.io/image2cpp/
 *       Canvas size  : 400 × 300
 *       Code output  : Plain bytes
 *       Draw mode    : Horizontal – 1 bit per pixel
 *
 *  3. Copy the generated byte array here, replacing the placeholder {}.
 *
 * SCREENS
 * ─────────────────────────────────────────────────────────────────────────────
 *  ui_boot_screen_ui       — Boot / splash screen
 *  ui_main_menu_ui         — Top-level menu
 *  ui_directory_view_ui    — Background frame for the file browser
 *                            (firmware renders text over this at runtime)
 *  ui_no_sd_card_ui        — No SD card detected
 *  ui_empty_directory_ui   — Folder contains no valid items
 *  ui_loading_ui           — "Loading…" transition screen
 *  ui_shutdown_ui          — "Powering off…" screen shown before latch cuts power
 *
 * Each array must be exactly 15000 bytes  (400 × 300 / 8 = 15000).
 * ─────────────────────────────────────────────────────────────────────────────
 */

